-- 2026-10-31p: MP Background timelines for batch 14, 25 more current MPs (owner's approval, "yes", 31 Oct 2026).
-- Sets background_timeline (357 entries, copied exactly from "background-batch14.json", which is not committed) and
-- background_last_checked = 2026-10-31 for member_ids 4020, 4026, 4029, 4030, 4040, 4048, 4051, 4056, 4066, 4076, 4084, 4089, 4095, 4118, 4125, 4126, 4138, 4139, 4243, 4245, 4253, 4264, 4268, 4269, 4277,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate(). Every source link was checked by Cowork
-- before the data file was written.
-- Nothing else changes. No code change. Backup of the 25 rows, off the repo: "Claude outputs/backups/2026-10-31p-mp-biography-before.csv".
-- Guards (RAISE): exactly 25 rows change, all of them these 25; the 271 existing timelines are unchanged (md5);
-- MPs with a timeline go from 271 to 296; each array equals the file exactly; 4178 entries in all afterwards.
-- Undo: 2026-10-31p-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (4020, 4026, 4029, 4030, 4040, 4048, 4051, 4056, 4066, 4076, 4084, 4089, 4095, 4118, 4125, 4126, 4138, 4139, 4243, 4245, 4253, 4264, 4268, 4269, 4277)) <> 25 THEN RAISE EXCEPTION 'expected 25 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (4020, 4026, 4029, 4030, 4040, 4048, 4051, 4056, 4066, 4076, 4084, 4089, 4095, 4118, 4125, 4126, 4138, 4139, 4243, 4245, 4253, 4264, 4268, 4269, 4277) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 271 THEN RAISE EXCEPTION 'expected 271 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
